    while (next < testFiles.length) {
      const result = await runOne(testFiles[next++]);
      results.push(result);
      onResult(result, results.length, testFiles.length);
    }
  };
  await Promise.all(Array.from({ length: Math.min(concurrency, testFiles.length) }, worker));
